INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (139, 284, 'SELF ADHESIVE TEAR TAPE (BOPP/BOPET cigarette tear tape)', '../upload/image/20180929/20180929104454_21225.jpg', '<p></p><p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">SELF ADHESIVE TEAR TAPE (BOPP/BOPET cigarette tear tape)</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Cigarette tear tape lines/Self adhesive tear tape /tear strip) were for packing/opening of cigarette packs. it is self adhesive tear tape.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Certification: ISO9001, ISO14001, OHSMS18000 </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">1) Various sizes:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">a) Thickness: 25-40UM</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">b) Width: 1.6mm-6.0mm</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">c) Length: 5,000m-70,000m</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">2) Printing design:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">a) Color printing: gold, single gold, single silver, solid red, yellow,white,black, etc.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">b) Logo printing: ink printing logo, laser, holographic effect</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">3.) Packing: Cartons (16rolls/carton)</span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-fami